import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import {
  ConversationEventType,
  type ConversationEvent,
  type EventMetadata,
  UtteranceType,
} from "../../types";
import { EventInfo } from "./EventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({
    title,
    onClose,
    children,
  }: {
    title: string;
    onClose: () => void;
    children: React.ReactNode;
  }) => (
    <div>
      <h1>{title}</h1>
      <button data-testid="event-details-close" onClick={onClose}>
        Close
      </button>
      {children}
    </div>
  ),
}));

function toolEvent(
  type: ConversationEventType,
  extraMetadata: Partial<EventMetadata> = {},
): ConversationEvent {
  return {
    __typename: "ConversationEvent",
    id: "1",
    conversationEventType: type,
    name: "lock_card",
    actionText: "",
    flowId: "",
    slotValue: null,
    value: null,
    stepId: "",
    timestamp: new Date().toISOString(),
    originalTimestamp: 0,
    metadata: {
      parseData: {},
      tool_name: "lock_card",
      ...extraMetadata,
    },
  };
}

describe("EventInfo tool-run routing", () => {
  it("routes mcp_tool_executed to the CALM panel", () => {
    renderWithProviders(
      <EventInfo
        event={toolEvent(ConversationEventType.McpToolExecuted, { tool_source: "mcp" })}
        onClose={vi.fn()}
        flows={[]}
      />,
    );

    expect(screen.getByText("MCP tool executed")).toBeInTheDocument();
    expect(screen.queryByText("Source")).not.toBeInTheDocument();
  });

  it("routes tool_executed to the Mantle panel", () => {
    renderWithProviders(
      <EventInfo
        event={toolEvent(ConversationEventType.ToolExecuted, { tool_source: "local" })}
        onClose={vi.fn()}
        flows={[]}
      />,
    );

    expect(screen.getByText("Tool executed")).toBeInTheDocument();
    expect(screen.getByText("Source")).toBeInTheDocument();
    expect(screen.getByText("local")).toBeInTheDocument();
  });
});

