describe("EventInfo voice-event routing", () => {
  it("routes user_input_suppressed to a focused input and decision panel", () => {
    const event = toolEvent(ConversationEventType.UserInputSuppressed, {
      barge_in_verdict: {
        accepted: false,
        reason: "backchannel",
        description: "backchannel (score 0.89 ≥ 0.75)",
        metadata: { word_count: 1, min_words: 3 },
      },
      reason: "backchannel (score 0.89 ≥ 0.75)",
    });
    event.text = "Okay.";

    renderWithProviders(<EventInfo event={event} onClose={vi.fn()} flows={[]} />);

    expect(screen.getByRole("heading", { name: "User input suppressed" })).toBeInTheDocument();
    expect(screen.getByText("Text")).toBeInTheDocument();
    expect(screen.getByText("Okay.")).toBeInTheDocument();
    expect(screen.getByText("Barge-in")).toBeInTheDocument();
    expect(screen.getByText("backchannel (score 0.89 ≥ 0.75)")).toBeInTheDocument();
    expect(screen.getByText("Event details")).toBeInTheDocument();
    expect(screen.queryByText("Event fields")).not.toBeInTheDocument();
    expect(screen.queryByText("Metadata")).not.toBeInTheDocument();
  });

  it("falls back to the verdict reason for events recorded without a reason", () => {
    const event = toolEvent(ConversationEventType.UserInputSuppressed, {
      barge_in_verdict: {
        accepted: false,
        reason: "below_min_words",
        metadata: { word_count: 2, min_words: 3 },
      },
    });

    renderWithProviders(<EventInfo event={event} onClose={vi.fn()} flows={[]} />);

    expect(screen.getByText("Barge-in")).toBeInTheDocument();
    expect(screen.getByText("below_min_words")).toBeInTheDocument();
  });

  it("routes user_silence_timeout to a focused timeout panel", () => {
    const event = toolEvent(ConversationEventType.UserSilenceTimeout);
    event.timeout = 7;

    renderWithProviders(<EventInfo event={event} onClose={vi.fn()} flows={[]} />);

    expect(screen.getByRole("heading", { name: "User silence timeout" })).toBeInTheDocument();
    expect(screen.getByText("Timeout")).toBeInTheDocument();
    expect(screen.getByText("7 seconds")).toBeInTheDocument();
    expect(screen.getByText("Event details")).toBeInTheDocument();
    expect(screen.queryByText("Event fields")).not.toBeInTheDocument();
    expect(screen.queryByText("Metadata")).not.toBeInTheDocument();
  });

  it("shows the suppression reason when no barge-in verdict is present", () => {
    const event = toolEvent(ConversationEventType.UserInputSuppressed);
    event.reason = "dtmf";

    renderWithProviders(<EventInfo event={event} onClose={vi.fn()} flows={[]} />);

    expect(screen.getByText("Suppression reason")).toBeInTheDocument();
    expect(screen.getByText("dtmf")).toBeInTheDocument();
    expect(screen.queryByText("Barge-in:")).not.toBeInTheDocument();
  });
});

describe("EventInfo history-entry routing", () => {
  function lifecycleEvent(
    type: ConversationEventType,
    overrides: Partial<ConversationEvent> = {},
  ): ConversationEvent {
    return {
      __typename: "ConversationEvent",
      id: "1",
      conversationEventType: type,
      name: "",
      actionText: "",
      slotValue: null,
      stepId: "",
      timestamp: new Date().toISOString(),
      originalTimestamp: 0,
      metadata: { parseData: {} },
      ...overrides,
    };
  }

  it("routes skill lifecycle events to the Mantle skill panel, not the flow panel", () => {
    renderWithProviders(
      <EventInfo
        event={lifecycleEvent(ConversationEventType.SkillActivated, { skillId: "my_skill" })}
        onClose={vi.fn()}
        flows={[]}
      />,
      { initialStoreState: { engineType: "mantle", skillCatalog: {} } },
    );

    expect(screen.getByText("Skill activated")).toBeInTheDocument();
    expect(screen.queryByText("Flow event")).not.toBeInTheDocument();
  });

  it("routes ordered-block lifecycle events to the Mantle block panel, not the flow panel", () => {
    renderWithProviders(
      <EventInfo
        event={lifecycleEvent(ConversationEventType.OrderedBlockEntered, {
          skillId: "my_skill",
          blockId: "my_block",
        })}
        onClose={vi.fn()}
        flows={[]}
      />,
      { initialStoreState: { engineType: "mantle", skillCatalog: {} } },
    );

    expect(screen.getByText("Block entered")).toBeInTheDocument();
    expect(screen.queryByText("Flow event")).not.toBeInTheDocument();
  });

  it("routes flow lifecycle events to the flow panel in flow-based projects", () => {
    renderWithProviders(
      <EventInfo
        event={lifecycleEvent(ConversationEventType.FlowStarted, { flowId: "my_flow" })}
        onClose={vi.fn()}
        flows={[]}
      />,
    );

    expect(screen.getByText("Flow event")).toBeInTheDocument();
  });
});

describe("EventInfo bot-message routing", () => {
  const botUtterance = {
    __typename: "Utterance" as const,
    id: "u1",
    metadata: { parseData: {} },
    rephrase: false,
    rephrasePrompt: null,
    text: "Hello",
    timestamp: "2020-01-01T00:00:00.000Z",
    tokens: [],
    type: UtteranceType.Bot,
    originalTimestamp: 0,
  };

  it("routes bot utterances to the agent response panel in flow-based projects", () => {
    renderWithProviders(<EventInfo event={botUtterance} onClose={vi.fn()} flows={[]} />);

    expect(screen.getByRole("heading", { name: /^Agent response details$/ })).toBeInTheDocument();
  });

  it("routes bot utterances to the same panel in skill mode", () => {
    renderWithProviders(<EventInfo event={botUtterance} onClose={vi.fn()} flows={[]} />, {
      initialStoreState: { engineType: "mantle", skillCatalog: {} },
    });

    expect(screen.getByRole("heading", { name: /^Agent response details$/ })).toBeInTheDocument();
  });
});
